<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Fresh Pantry — Discover Everyday Deliciousness</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Nunito:wght@600;700;800&family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
  <style>
    :root {
      --green: #2D6A4F;
      --green-soft: #3f7f62;
      --accent: #F4A261;
      --cream: #FEFAE0;
      --text: #253529;
      --muted: #5f6f63;
      --card: #ffffff;
      --sunny: #f8c85c;
      --shadow: 0 10px 25px rgba(45, 106, 79, 0.12);
      --radius: 18px;
      --radius-sm: 12px;
      --max: 1120px;
    }

    * { box-sizing: border-box; }
    html { scroll-behavior: smooth; }
    body {
      margin: 0;
      font-family: 'Inter', system-ui, -apple-system, Segoe UI, sans-serif;
      color: var(--text);
      background: linear-gradient(180deg, #fffef4 0%, var(--cream) 60%, #fffdf2 100%);
      line-height: 1.55;
    }

    .container { width: min(var(--max), 92vw); margin: 0 auto; }
    section { padding: 56px 0; }

    h1, h2, h3, .logo, .stat-number {
      font-family: 'Nunito', 'Inter', sans-serif;
      margin: 0;
      line-height: 1.2;
    }

    .badge {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      font-size: 0.86rem;
      color: var(--green);
      background: #ecf7ef;
      border: 1px solid #d7efdf;
      padding: 7px 12px;
      border-radius: 999px;
      font-weight: 700;
    }

    header {
      position: sticky;
      top: 0;
      z-index: 30;
      backdrop-filter: blur(8px);
      background: rgba(254, 250, 224, 0.9);
      border-bottom: 1px solid rgba(45, 106, 79, 0.12);
    }

    .topbar {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 14px 0;
      gap: 20px;
    }

    .logo {
      font-size: 1.45rem;
      font-weight: 800;
      color: var(--green);
      letter-spacing: 0.2px;
    }

    nav ul {
      margin: 0;
      padding: 0;
      list-style: none;
      display: flex;
      gap: 20px;
      flex-wrap: wrap;
    }

    nav a {
      text-decoration: none;
      color: var(--text);
      font-weight: 600;
      font-size: 0.96rem;
      padding: 8px 10px;
      border-radius: 10px;
      transition: background 0.2s ease, color 0.2s ease;
    }

    nav a:hover, nav a:focus-visible {
      background: #e7f3ea;
      color: var(--green);
      outline: none;
    }

    .hero {
      padding-top: 72px;
      display: grid;
      grid-template-columns: 1.15fr 1fr;
      gap: 34px;
      align-items: center;
    }

    .hero h1 {
      font-size: clamp(2rem, 4vw, 3.25rem);
      margin: 14px 0 14px;
      color: var(--green);
    }

    .hero p {
      font-size: 1.05rem;
      color: var(--muted);
      max-width: 55ch;
      margin-bottom: 24px;
    }

    .hero-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 12px;
    }

    .btn {
      border: 0;
      border-radius: 999px;
      padding: 12px 18px;
      font-weight: 700;
      cursor: pointer;
      font-family: inherit;
      font-size: 0.95rem;
      transition: transform .2s ease, box-shadow .2s ease, background .2s ease;
      text-decoration: none;
      display: inline-flex;
      align-items: center;
      justify-content: center;
    }

    .btn-primary {
      background: var(--green);
      color: #fff;
      box-shadow: var(--shadow);
    }

    .btn-secondary {
      background: #fff;
      color: var(--green);
      border: 1px solid #dbe9df;
    }

    .btn:hover, .btn:focus-visible { transform: translateY(-1px); outline: none; }

    .hero-image {
      border-radius: 24px;
      overflow: hidden;
      box-shadow: var(--shadow);
      min-height: 340px;
      background: #ddd;
      position: relative;
    }

    .hero-image img { width: 100%; height: 100%; object-fit: cover; display: block; }

    .section-head {
      display: flex;
      align-items: end;
      justify-content: space-between;
      gap: 14px;
      margin-bottom: 20px;
    }

    .section-head h2 { font-size: clamp(1.4rem, 3vw, 2rem); color: var(--green); }
    .section-head p { margin: 0; color: var(--muted); }

    .carousel-wrap { position: relative; }
    .carousel-track {
      display: grid;
      grid-auto-flow: column;
      grid-auto-columns: minmax(220px, 1fr);
      gap: 16px;
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      padding: 4px;
      scroll-behavior: smooth;
      scrollbar-width: none;
    }
    .carousel-track::-webkit-scrollbar { display: none; }

    .product-card {
      scroll-snap-align: start;
      background: var(--card);
      border-radius: var(--radius);
      overflow: hidden;
      box-shadow: var(--shadow);
      border: 1px solid #eef3ec;
      display: flex;
      flex-direction: column;
    }

    .product-card img { width: 100%; height: 150px; object-fit: cover; }
    .product-content { padding: 14px; display: grid; gap: 8px; }
    .product-title { font-weight: 800; font-size: 1.02rem; color: var(--green); }
    .product-desc { font-size: .9rem; color: var(--muted); min-height: 42px; }
    .price { font-weight: 800; color: #a7541f; }

    .carousel-controls {
      display: flex;
      gap: 10px;
    }

    .arrow {
      border: 0;
      width: 40px;
      height: 40px;
      border-radius: 50%;
      background: #fff;
      box-shadow: var(--shadow);
      cursor: pointer;
      font-size: 1.1rem;
      color: var(--green);
    }

    .seasonal-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(230px, 1fr));
      gap: 16px;
    }

    .seasonal-card {
      background: #fff;
      border: 1px solid #f2e6db;
      border-radius: var(--radius-sm);
      padding: 16px;
      box-shadow: 0 8px 18px rgba(244, 162, 97, 0.14);
    }

    .seasonal-card h3 { color: #9a4d1e; margin-bottom: 6px; font-size: 1.03rem; }
    .seasonal-card p { margin: 0 0 8px; color: #6e655f; font-size: .92rem; }

    .highlights {
      background: linear-gradient(90deg, var(--green) 0%, var(--green-soft) 100%);
      border-radius: 24px;
      padding: 26px;
      color: #fff;
      box-shadow: var(--shadow);
      margin-top: 22px;
    }

    .stats {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
      gap: 16px;
    }

    .stat { background: rgba(255,255,255,.08); border-radius: 14px; padding: 14px; }
    .stat-number { font-size: 1.8rem; font-weight: 800; color: #fff8cc; }
    .stat-label { font-size: .94rem; opacity: .95; }

    .categories-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
      gap: 14px;
    }

    .category {
      position: relative;
      border-radius: 16px;
      overflow: hidden;
      min-height: 180px;
      cursor: pointer;
      box-shadow: var(--shadow);
      transform: translateZ(0);
      transition: transform .25s ease;
    }

    .category img { width: 100%; height: 100%; object-fit: cover; display: block; }
    .category:hover, .category:focus-visible { transform: scale(1.03); outline: none; }

    .category-overlay {
      position: absolute;
      inset: 0;
      background: linear-gradient(to top, rgba(27, 53, 41, .7), rgba(27,53,41,.25));
      display: flex;
      align-items: end;
      padding: 14px;
      color: #fff;
      font-weight: 800;
      font-family: 'Nunito', sans-serif;
      letter-spacing: .2px;
    }

    .locator-wrap, .newsletter-wrap {
      background: #fff;
      border-radius: 20px;
      border: 1px solid #ebf0e8;
      box-shadow: var(--shadow);
      padding: 24px;
    }

    .input-row {
      display: flex;
      gap: 10px;
      flex-wrap: wrap;
      margin-top: 14px;
    }

    input[type="text"], input[type="email"] {
      flex: 1 1 240px;
      border: 1px solid #d9e7dc;
      border-radius: 12px;
      padding: 12px 14px;
      font-size: .95rem;
      font-family: inherit;
    }

    .results {
      margin-top: 16px;
      display: grid;
      gap: 10px;
    }

    .store-card {
      border: 1px solid #e8f1eb;
      border-radius: 12px;
      padding: 12px;
      background: #fbfefc;
      display: grid;
      gap: 4px;
      font-size: .93rem;
    }

    .store-name { font-weight: 800; color: var(--green); }

    .confirm {
      margin-top: 10px;
      color: var(--green);
      font-weight: 700;
      display: none;
    }

    footer {
      padding: 36px 0 24px;
      margin-top: 26px;
      background: #f6f3dd;
      border-top: 1px solid #e5e3cb;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
      gap: 16px;
      margin-bottom: 18px;
    }

    .footer-group h4 { margin: 0 0 8px; color: var(--green); font-family: 'Nunito', sans-serif; }
    .footer-group p { margin: 3px 0; color: #57665b; font-size: .92rem; }
    .tagline { color: #5f6f63; font-size: .9rem; }

    @media (max-width: 820px) {
      .hero { grid-template-columns: 1fr; }
      .topbar { flex-direction: column; align-items: flex-start; }
      .section-head { align-items: flex-start; flex-direction: column; }
    }
  </style>
</head>
<body>
  <header>
    <div class="container topbar">
      <div class="logo">Fresh Pantry</div>
      <nav aria-label="Primary">
        <ul>
          <li><a href="#featured-products">Products</a></li>
          <li><a href="#store-locator">Our Stores</a></li>
          <li><a href="#seasonal-picks">Recipes</a></li>
          <li><a href="#footer">About Us</a></li>
        </ul>
      </nav>
    </div>
  </header>

  <main>
    <section class="container hero" id="hero">
      <div>
        <span class="badge">🌿 Neighborhood Grocery Magic</span>
        <h1>Discover Everyday Deliciousness</h1>
        <p>Unique flavors, quality ingredients, and unbeatable prices — all waiting for you at your neighborhood Fresh Pantry.</p>
        <div class="hero-actions">
          <a class="btn btn-primary" href="#store-locator">Find a Store Near You</a>
          <a class="btn btn-secondary" href="#featured-products">Explore This Week's Picks</a>
        </div>
      </div>
      <div class="hero-image" aria-hidden="true">
        <img src="https://images.unsplash.com/photo-1542838132-92c53300491e?auto=format&fit=crop&w=1200&q=80" alt="Bright grocery produce aisle" />
      </div>
    </section>

    <section class="container" id="featured-products">
      <div class="section-head">
        <div>
          <h2>Featured Products</h2>
          <p>Staff favorites you’ll want in your cart this week.</p>
        </div>
        <div class="carousel-controls" aria-label="Carousel controls">
          <button class="arrow" id="prevBtn" aria-label="Previous products">←</button>
          <button class="arrow" id="nextBtn" aria-label="Next products">→</button>
        </div>
      </div>

      <div class="carousel-wrap">
        <div class="carousel-track" id="productTrack">
          <article class="product-card">
            <img src="https://images.unsplash.com/photo-1515003197210-e0cd71810b5f?auto=format&fit=crop&w=800&q=80" alt="Organic Maple Granola" />
            <div class="product-content">
              <div class="product-title">Organic Maple Granola</div>
              <div class="product-desc">Crunchy clusters with real maple syrup and toasted oats</div>
              <div class="price">$3.99</div>
            </div>
          </article>

          <article class="product-card">
            <img src="https://images.unsplash.com/photo-1473093295043-cdd812d0e601?auto=format&fit=crop&w=800&q=80" alt="Everything But The Bagel Seasoning" />
            <div class="product-content">
              <div class="product-title">Everything But The Bagel Seasoning</div>
              <div class="product-desc">A savory blend of sesame, garlic, onion & poppy seeds</div>
              <div class="price">$2.49</div>
            </div>
          </article>

          <article class="product-card">
            <img src="https://images.unsplash.com/photo-1548907040-4baa42d10919?auto=format&fit=crop&w=800&q=80" alt="Dark Chocolate Peanut Butter Cups" />
            <div class="product-content">
              <div class="product-title">Dark Chocolate Peanut Butter Cups</div>
              <div class="product-desc">Rich dark chocolate with creamy peanut butter filling</div>
              <div class="price">$3.49</div>
            </div>
          </article>

          <article class="product-card">
            <img src="https://images.unsplash.com/photo-1547592166-23ac45744acd?auto=format&fit=crop&w=800&q=80" alt="Cauliflower Gnocchi" />
            <div class="product-content">
              <div class="product-title">Cauliflower Gnocchi</div>
              <div class="product-desc">Light, pillowy gnocchi made with real cauliflower</div>
              <div class="price">$2.99</div>
            </div>
          </article>

          <article class="product-card">
            <img src="https://images.unsplash.com/photo-1603133872878-684f208fb84b?auto=format&fit=crop&w=800&q=80" alt="Mandarin Orange Chicken" />
            <div class="product-content">
              <div class="product-title">Mandarin Orange Chicken</div>
              <div class="product-desc">Crispy chicken bites in a sweet & tangy mandarin sauce</div>
              <div class="price">$4.99</div>
            </div>
          </article>

          <article class="product-card">
            <img src="https://images.unsplash.com/photo-1486297678162-eb2a19b0a32d?auto=format&fit=crop&w=800&q=80" alt="Unexpected Cheddar Cheese" />
            <div class="product-content">
              <div class="product-title">Unexpected Cheddar Cheese</div>
              <div class="product-desc">Aged cheddar with crystalline crunch and complex flavor</div>
              <div class="price">$3.99</div>
            </div>
          </article>

          <article class="product-card">
            <img src="https://images.unsplash.com/photo-1600271886742-f049cd451bba?auto=format&fit=crop&w=800&q=80" alt="Spicy Mango Lemonade" />
            <div class="product-content">
              <div class="product-title">Spicy Mango Lemonade</div>
              <div class="product-desc">Tropical mango with a kick of chili and fresh lemon</div>
              <div class="price">$2.79</div>
            </div>
          </article>

          <article class="product-card">
            <img src="https://images.unsplash.com/photo-1508747703725-719777637510?auto=format&fit=crop&w=800&q=80" alt="Truffle Marcona Almonds" />
            <div class="product-content">
              <div class="product-title">Truffle Marcona Almonds</div>
              <div class="product-desc">Roasted marcona almonds dusted with black truffle salt</div>
              <div class="price">$4.49</div>
            </div>
          </article>
        </div>
      </div>

      <div class="highlights" aria-label="Brand highlights">
        <div class="stats">
          <div class="stat">
            <div class="stat-number">500+</div>
            <div class="stat-label">Stores Nationwide</div>
          </div>
          <div class="stat">
            <div class="stat-number">4,000+</div>
            <div class="stat-label">Unique Products</div>
          </div>
          <div class="stat">
            <div class="stat-number">80%</div>
            <div class="stat-label">Private Label Items</div>
          </div>
          <div class="stat">
            <div class="stat-number">Weekly</div>
            <div class="stat-label">New Items Every Week</div>
          </div>
        </div>
      </div>
    </section>

    <section class="container" id="seasonal-picks">
      <div class="section-head">
        <div>
          <h2>Summer Favorites Are Here 🌞</h2>
          <p>Limited-time flavors crafted for the season — grab them before they're gone!</p>
        </div>
      </div>
      <div class="seasonal-grid">
        <article class="seasonal-card">
          <h3>Watermelon Mint Sparkling Water</h3>
          <p>Refreshing fizz with real watermelon essence and a hint of mint.</p>
          <div class="price">$1.99</div>
        </article>
        <article class="seasonal-card">
          <h3>Grilled Peach & Burrata Salad Kit</h3>
          <p>Everything you need for a summer salad in one box.</p>
          <div class="price">$5.49</div>
        </article>
        <article class="seasonal-card">
          <h3>Coconut Cold Brew Concentrate</h3>
          <p>Smooth, creamy cold brew with natural coconut flavor.</p>
          <div class="price">$6.99</div>
        </article>
        <article class="seasonal-card">
          <h3>Mango Sticky Rice Spring Rolls</h3>
          <p>A sweet twist on a classic, ready in minutes.</p>
          <div class="price">$3.99</div>
        </article>
      </div>
    </section>

    <section class="container" id="categories">
      <div class="section-head">
        <div>
          <h2>Shop By Category</h2>
          <p>Find what you love, from essentials to crave-worthy treats.</p>
        </div>
      </div>
      <div class="categories-grid">
        <article class="category" tabindex="0">
          <img src="https://images.unsplash.com/photo-1619734240011-7f8f35f0f4c0?auto=format&fit=crop&w=900&q=80" alt="Snacks and sweets" />
          <div class="category-overlay">Snacks & Sweets</div>
        </article>
        <article class="category" tabindex="0">
          <img src="https://images.unsplash.com/photo-1610832958506-aa56368176cf?auto=format&fit=crop&w=900&q=80" alt="Fresh produce" />
          <div class="category-overlay">Fresh Produce</div>
        </article>
        <article class="category" tabindex="0">
          <img src="https://images.unsplash.com/photo-1584473457493-17c4dfb39b70?auto=format&fit=crop&w=900&q=80" alt="Frozen favorites" />
          <div class="category-overlay">Frozen Favorites</div>
        </article>
        <article class="category" tabindex="0">
          <img src="https://images.unsplash.com/photo-1523362628745-0c100150b504?auto=format&fit=crop&w=900&q=80" alt="Beverages" />
          <div class="category-overlay">Beverages</div>
        </article>
        <article class="category" tabindex="0">
          <img src="https://images.unsplash.com/photo-1488477181946-6428a0291777?auto=format&fit=crop&w=900&q=80" alt="Dairy and cheese" />
          <div class="category-overlay">Dairy & Cheese</div>
        </article>
      </div>
    </section>

    <section class="container" id="store-locator">
      <div class="locator-wrap">
        <div class="section-head">
          <div>
            <h2>Find Your Fresh Pantry</h2>
            <p>Enter your zip code to discover the nearest store, hours, and directions.</p>
          </div>
        </div>
        <div class="input-row">
          <input id="zipInput" type="text" placeholder="Enter your zip code" aria-label="Zip code" maxlength="10" />
          <button id="searchStores" class="btn btn-primary" type="button">Search</button>
        </div>
        <div id="storeResults" class="results" aria-live="polite"></div>
      </div>
    </section>

    <section class="container" id="newsletter">
      <div class="newsletter-wrap">
        <div class="section-head">
          <div>
            <h2>Stay Fresh 🍋</h2>
            <p>Sign up for weekly deals, new product alerts, and seasonal recipes delivered to your inbox.</p>
          </div>
        </div>
        <div class="input-row">
          <input id="emailInput" type="email" placeholder="Your email address" aria-label="Email address" />
          <button id="subscribeBtn" class="btn btn-secondary" type="button">Subscribe</button>
        </div>
        <div id="subscribeConfirm" class="confirm">Thanks for subscribing! Check your inbox for a welcome treat.</div>
      </div>
    </section>
  </main>

  <footer id="footer">
    <div class="container">
      <div class="footer-grid">
        <div class="footer-group">
          <h4>Shop</h4>
          <p>Products</p>
          <p>Seasonal Picks</p>
          <p>New Arrivals</p>
          <p>Gift Cards</p>
        </div>
        <div class="footer-group">
          <h4>Company</h4>
          <p>About Us</p>
          <p>Careers</p>
          <p>Press</p>
          <p>Sustainability</p>
        </div>
        <div class="footer-group">
          <h4>Help</h4>
          <p>Store Locator</p>
          <p>FAQs</p>
          <p>Contact Us</p>
          <p>Accessibility</p>
        </div>
        <div class="footer-group">
          <h4>Follow Us</h4>
          <p>Instagram</p>
          <p>Facebook</p>
          <p>Pinterest</p>
          <p>TikTok</p>
        </div>
      </div>
      <div class="tagline">© 2024 Fresh Pantry. Discover Everyday Deliciousness.</div>
    </div>
  </footer>

  <script>
    const track = document.getElementById('productTrack');
    const nextBtn = document.getElementById('nextBtn');
    const prevBtn = document.getElementById('prevBtn');

    const scrollAmount = () => Math.min(track.clientWidth * 0.85, 900);

    nextBtn.addEventListener('click', () => {
      track.scrollBy({ left: scrollAmount(), behavior: 'smooth' });
    });

    prevBtn.addEventListener('click', () => {
      track.scrollBy({ left: -scrollAmount(), behavior: 'smooth' });
    });

    const stores = [
      {
        name: 'Fresh Pantry — Lincoln Park',
        address: '2140 N. Halsted St, Chicago, IL 60614',
        hours: '8am – 9pm Daily',
        distance: '0.8 mi'
      },
      {
        name: 'Fresh Pantry — Wicker Park',
        address: '1840 W. North Ave, Chicago, IL 60622',
        hours: '8am – 9pm Daily',
        distance: '1.4 mi'
      },
      {
        name: 'Fresh Pantry — Lakeview',
        address: '3745 N. Lincoln Ave, Chicago, IL 60613',
        hours: '8am – 9pm Daily',
        distance: '2.1 mi'
      }
    ];

    const zipInput = document.getElementById('zipInput');
    const searchStores = document.getElementById('searchStores');
    const storeResults = document.getElementById('storeResults');

    function renderStores() {
      storeResults.innerHTML = stores.map(store => `
        <article class="store-card">
          <div class="store-name">${store.name}</div>
          <div>${store.address}</div>
          <div><strong>Hours:</strong> ${store.hours}</div>
          <div><strong>Distance:</strong> ${store.distance}</div>
        </article>
      `).join('');
    }

    searchStores.addEventListener('click', () => {
      const value = zipInput.value.trim();
      if (!value) {
        storeResults.innerHTML = '<div class="store-card">Please enter a zip code to search nearby stores.</div>';
        return;
      }
      renderStores();
    });

    zipInput.addEventListener('keydown', (event) => {
