    const searchStores = document.getElementById('searchStores');
    const storeResults = document.getElementById('storeResults');

    function renderStores() {
      storeResults.innerHTML = stores.map(store => `
        <article class="store-card">
          <div class="store-name">${store.name}</div>
          <div>${store.address}</div>
          <div><strong>Hours:</strong> ${store.hours}</div>
          <div><strong>Distance:</strong> ${store.distance}</div>
        </article>
      `).join('');
    }

    searchStores.addEventListener('click', () => {
      const value = zipInput.value.trim();
      if (!value) {
        storeResults.innerHTML = '<div class="store-card">Please enter a zip code to search nearby stores.</div>';
        return;
      }
      renderStores();
    });

    zipInput.addEventListener('keydown', (event) => {
      if (event.key === 'Enter') searchStores.click();
    });

    const emailInput = document.getElementById('emailInput');
    const subscribeBtn = document.getElementById('subscribeBtn');
    const subscribeConfirm = document.getElementById('subscribeConfirm');

    subscribeBtn.addEventListener('click', () => {
      const email = emailInput.value.trim();
      if (!email || !email.includes('@')) {
        subscribeConfirm.textContent = 'Please enter a valid email address.';
        subscribeConfirm.style.display = 'block';
        return;
      }
      subscribeConfirm.textContent = 'Thanks for subscribing! Check your inbox for a welcome treat.';
      subscribeConfirm.style.display = 'block';
      emailInput.value = '';
    });
  </script>
</body>
